	"deleted_at" timestamp with time zone,
	"post_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "conversation_title_check" CHECK (char_length(title) <= 120),
	CONSTRAINT "conversation_kind_check" CHECK (kind in ('normal', 'ree_test', 'mcp')),
	CONSTRAINT "conversation_ree_test_check" CHECK ((kind = 'ree_test') = (ree_id is not null))
);
